322→test("the recorded three-channel session yields recalled and injected, and no selected", () => {
323→  // The snapshot is a committed fixture, not the live artifact under
324→  // provenance/artifacts/. That file is rewritten every time a pool is frozen,
325→  // so a test reading it asserts against whichever pool happened to be current
326→  // — this test broke the moment the evaluation pool replaced the old team's.
327→  // A test about a *recorded* session has to use the pool as it was for that
328→  // session.
329→  const snapshot = JSON.parse(readFileSync("evaluation/contracts/fixtures/pool-snapshot-gate0-session.json", "utf8"));
330→  const captureEvents = parseJsonl(readFileSync("evaluation/gate0/artifacts/gate0-threechannel-capture.jsonl", "utf8"));
331→  const toolCallRows = parseJsonl(readFileSync("evaluation/gate0/artifacts/tool-call-logs.jsonl", "utf8"));
332→
333→  const { events, unresolved } = buildEarlyEvents({ snapshot, toolCallRows, captureEvents });
334→  const byState = {};
335→  for (const e of events) byState[e.state] = (byState[e.state] ?? 0) + 1;
336→
337→  assert.equal(byState.recalled, 2, "both skills came back from one skill/search");
338→  assert.equal(byState.injected, 2);
339→  assert.equal(byState.selected ?? 0, 0, "no candidate log was recorded for that session");
340→
341→  // The memory hits in that session are real, and the snapshot covers only
342→  // skill and knowledge. They are reported as unresolved rather than dropped.
343→  assert.ok(Object.keys(unresolved).some((k) => k.startsWith("listing:m_")));
344→});
